namespace ghidra.app.events;



using ghidra.framework.plugintool;
using ghidra.program.model.listing;

/**
 * Event for telling a tool to close a program
 */
public class CloseProgramPluginEvent : PluginEvent {

	static readonly string NAME = "Close Program";

	private WeakReference<Program> programRef;
	private bool ignoreChanges;

	/**
	 * Construct a new plugin event.
	 * @param source name of the plugin that created this event
	 * @param p the program associated with this event
	 * @param ignoreChanges true to ignore changes
	 */
	public CloseProgramPluginEvent(string source, Program p, bool ignoreChanges) : base(source, NAME)
    {
		this.programRef = new(p);
		this.ignoreChanges = ignoreChanges;
	}

	/**
	 * Return the program on this event.
	 * @return null if the event if for a program closing.
	 */
	public Program getProgram() {
		return programRef.get();
	}

	public bool ignoreChanges() {
		return ignoreChanges;
	}
}
